<?php ob_start(); ?><section class="hero"><p class="eyebrow">Campus Rooms</p><h1>Des espaces clairs pour des journees bien reservees.</h1><p>Consultez les salles disponibles et planifiez vos activites sans doublon.</p><a class="button" href="/salles/create">Ajouter une salle</a></section><section class="section"><div class="section-head"><h2>Les salles</h2><span><?= count($salles) ?> espaces</span></div><div class="grid"><?php foreach ($salles as $salle): ?><article class="card"><div class="card-top"><span class="tag"><?= htmlspecialchars($salle->type) ?></span><span class="status <?= $salle->active ? 'on' : 'off' ?>"><?= $salle->active ? 'Active' : 'Inactive' ?></span></div><h3><a href="/salles/<?= $salle->id ?>"><?= htmlspecialchars($salle->nom) ?></a></h3><p><?= htmlspecialchars($salle->batiment) ?> · <?= $salle->capacite ?> places</p></article><?php endforeach; ?></div></section><?php $content = ob_get_clean(); require dirname(__DIR__) . '/layout/base.php';